      code: "import { ShardingManager } from '@jubbio/core';\n\nconst manager = new ShardingManager('./bot.js', {\n  totalShards: 'auto',\n  token: process.env.BOT_TOKEN\n});\n\nmanager.on('shardReady', (shardId) => {\n  console.log(`Shard ${shardId} hazır`);\n});\n\nmanager.on('shardDeath', (shardId, info) => {\n  console.log(`Shard ${shardId} öldü. Kod: ${info.code}`);\n});\n\nmanager.on('shardError', (shardId, error) => {\n  console.error(`Shard ${shardId} hatası:`, error);\n});\n\nmanager.spawn();"
