      code: "import { Client, GatewayIntentBits } from '@jubbio/core';\n\nconst client = new Client({\n  intents: [GatewayIntentBits.Guilds, GatewayIntentBits.GuildMessages]\n});\n\nclient.on('ready', () => {\n  console.log(`Shard ${client.shard.id} hazır (toplam: ${client.shard.count})`);\n\n  // KRİTİK: Manager'a ready olduğunu bildir\n  client.shard.ready();\n});\n\nclient.on('messageCreate', async (message) => {\n  if (message.content === '!stats') {\n    // Tüm shard'lardan sunucu sayısını topla\n    const results = await client.shard.fetchClientValues('guilds.size');\n    const total = results.reduce((a, b) => a + b, 0);\n    await message.reply(`Toplam ${total} sunucu (${results.length} shard)`);\n  }\n});\n\nclient.login(process.env.JUBBIO_TOKEN);"
